import type { QualityLevel } from "../../core/types.js";

/** Returns quality levels sorted from highest to lowest. */
export function normalizeQualityLevels(levels: readonly QualityLevel[]): readonly QualityLevel[] {
  return [...levels].sort((left, right) => {
    const leftRank = left.height ?? left.bitrate ?? 0;
    const rightRank = right.height ?? right.bitrate ?? 0;
    return rightRank - leftRank;
  });
}

/** Finds a quality level by id. */
export function findQuality(
  levels: readonly QualityLevel[],
  id: string | null,
): QualityLevel | null {
  if (id === null) {
    return null;
  }

  return levels.find((level) => level.id === id) ?? null;
}

/**
 * Steps through the quality ladder.
 *
 * Levels are ordered highest first. A positive `direction` moves to a higher
 * quality, a negative one to a lower quality. Passing the edge of the ladder
 * selects automatic quality (`null`). When automatic quality is active, the
 * first step picks the highest or lowest level in that direction.
 */
export function stepQuality(
  levels: readonly QualityLevel[],
  currentId: string | null,
  direction: number,
): string | null {
  const sorted = normalizeQualityLevels(levels);

  if (sorted.length === 0 || direction === 0) {
    return currentId;
  }

  const index = sorted.findIndex((level) => level.id === currentId);

  if (index < 0) {
    return direction > 0 ? (sorted[0]?.id ?? null) : (sorted[sorted.length - 1]?.id ?? null);
  }

  const next = index + (direction > 0 ? -1 : 1);
  return next < 0 || next >= sorted.length ? null : (sorted[next]?.id ?? null);
}

/** Human-readable label for a quality level. */
export function qualityLabel(level: QualityLevel): string {
  if (level.label.length > 0) {
    return level.label;
  }

  if (level.height !== undefined) {
    return `${level.height}p`;
  }

  if (level.bitrate !== undefined) {
    return `${Math.round(level.bitrate / 1000)} kbps`;
  }

  return level.id;
}
